def is_valid_schedule(shifts):
    # Check if the schedule is empty
    if not shifts:
        return True

    # Check rule 1: each shift has start < end and is within 0 to 1440
    for start, end in shifts:
        if not (0 <= start < end <= 1440):
            return False

    # Check rule 2: each shift is at least 30 and at most 240 minutes
    for start, end in shifts:
        duration = end - start
        if not (30 <= duration <= 240):
            return False

    # Check rule 3: shifts may not overlap
    # Sort shifts by start time to check for overlaps
    sorted_shifts = sorted(shifts, key=lambda x: x[0])
    for i in range(len(sorted_shifts) - 1):
        current_end = sorted_shifts[i][1]
        next_start = sorted_shifts[i + 1][0]
        if next_start < current_end:
            return False

    # Check rule 4: between the end of one shift and the start of the next, there must be a break of at least 15 minutes
    for i in range(len(sorted_shifts) - 1):
        current_end = sorted_shifts[i][1]
        next_start = sorted_shifts[i + 1][0]
        if next_start - current_end < 15:
            return False

    # Check rule 5: total scheduled time is at most 600 minutes
    total_time = sum(end - start for start, end in shifts)
    if total_time > 600:
        return False

    return True
```

