def merge_settings(defaults, overrides):
    # Create a new dictionary to hold the merged settings
    merged = {}

    # Iterate over each key in the overrides dictionary
    for key in overrides:
        # If the override value is None, remove the key from the result
        if overrides[key] is None:
            if key in defaults:
                del merged[key]
            continue

        # Check if the default value is a dictionary
        if isinstance(defaults.get(key), dict):
            # Check if the override value is also a dictionary
            if isinstance(overrides[key], dict):
                # Merge the dictionaries recursively
                merged[key] = merge_settings(defaults[key], overrides[key])
            else:
                # Replace the default value with the override value
                merged[key] = overrides[key]
        else:
            # Replace the default value with the override value
            merged[key] = overrides[key]

    # Add the default values that are not overridden
    for key in defaults:
        if key not in merged:
            merged[key] = defaults[key]

    return merged
```

